def main(data: str) -> dict:
    import json

    try:
        if isinstance(data, dict):
            obj = data
        elif isinstance(data, str):
            text = data.strip()
            if not text:
                raise ValueError("data为空")
            obj = json.loads(text)
        else:
            raise TypeError("data必须是JSON字符串或Object")

        if not isinstance(obj, dict):
            raise TypeError("data解析结果必须是Object")

        return {
            "parsed_data": obj,
            "parse_ok": True,
            "parse_err": ""
        }
    except Exception as exc:
        return {
            "parsed_data": {},
            "parse_ok": False,
            "parse_err": str(exc)
        }

def main(parsed_data: dict, parse_ok: bool, parse_err: str) -> dict:
    from datetime import datetime

    if not parse_ok:
        raise ValueError(f"JSON解析失败：{parse_err or '未知解析错误'}")

    errors = []
    warnings = []
    checks = []

    required = [
        "任务信息", "文档信息", "节假日概况", "天气信息", "客流预测",
        "重点信息", "重点车站", "运输安排", "运营保障",
        "附录数据"
    ]
    for group in required:
        if group not in parsed_data:
            errors.append(f"缺少顶层数据组：{group}")

    if errors:
        raise ValueError("数据质量校验失败：" + "；".join(errors))

    def parse_date(path, value):
        try:
            return datetime.strptime(str(value), "%Y-%m-%d").date()
        except Exception:
            errors.append(f"{path}必须是YYYY-MM-DD日期")
            return None

    def nonnegative(path, value):
        if not isinstance(value, (int, float)) or value < 0:
            errors.append(f"{path}必须是非负数")

    task = parsed_data["任务信息"]
    for field in ["任务编号", "任务名称", "城市", "节假日", "保障年份", "输出文件名"]:
        if task.get(field) in (None, ""):
            errors.append(f"任务信息.{field}不能为空")

    holiday = parsed_data["节假日概况"]
    start = parse_date("节假日概况.开始日期", holiday.get("开始日期"))
    end = parse_date("节假日概况.结束日期", holiday.get("结束日期"))
    impact_start = parse_date("节假日概况.保障期开始日期", holiday.get("保障期开始日期"))
    impact_end = parse_date("节假日概况.保障期结束日期", holiday.get("保障期结束日期"))
    if start and end:
        if start > end:
            errors.append("节假日开始日期不得晚于结束日期")
        expected_days = (end - start).days + 1
        checks.append({"name": "放假天数闭合", "passed": holiday.get("放假天数") == expected_days})
        if holiday.get("放假天数") != expected_days:
            errors.append("节假日放假天数与日期范围不一致")
    if start and end and impact_start and impact_end:
        covered = impact_start <= start and impact_end >= end
        checks.append({"name": "保障期覆盖假期", "passed": covered})
        if not covered:
            errors.append("保障期未完整覆盖节假日")

    weather_rows = parsed_data["天气信息"].get("逐日天气", [])
    if not weather_rows:
        errors.append("天气信息.逐日天气不能为空")
    weather_dates = [x.get("日期") for x in weather_rows]
    if len(weather_dates) != len(set(weather_dates)):
        errors.append("逐日天气存在重复日期")

    forecast = parsed_data["客流预测"]
    line_rows = forecast.get("各线路客运量预测", [])
    section_rows = forecast.get("重点区段断面客流预测", [])
    if not line_rows:
        errors.append("客流预测.各线路客运量预测不能为空")
    if not section_rows:
        warnings.append("客流预测.重点区段断面客流预测为空")
    line_names = [x.get("线路") for x in line_rows]
    if any(not x for x in line_names) or len(line_names) != len(set(line_names)):
        errors.append("各线路客运量预测的线路必须非空且唯一")

    transport = parsed_data["运输安排"]
    pre = transport.get("节前一日", {})
    pre_rows = pre.get("各线路方案", [])
    for row in pre_rows:
        nonnegative(f"节前一日.{row.get('线路')}.上线列车数", row.get("上线列车数"))
        nonnegative(f"节前一日.{row.get('线路')}.备用车数", row.get("备用车数"))
    pre_online = sum(x.get("上线列车数", 0) for x in pre_rows)
    pre_reserve = sum(x.get("备用车数", 0) for x in pre_rows)
    pre_online_ok = pre_online == pre.get("上线列车合计")
    pre_reserve_ok = pre_reserve == pre.get("备用车合计")
    checks.extend([
        {"name": "节前上线列车闭合", "passed": pre_online_ok},
        {"name": "节前备用车闭合", "passed": pre_reserve_ok}
    ])
    if not pre_online_ok:
        errors.append("节前各线路上线列车数之和不等于线网合计")
    if not pre_reserve_ok:
        errors.append("节前各线路备用车数之和不等于线网合计")

    appendices = parsed_data["附录数据"]
    appendix_numbers = sorted(
        x.get("附录编号") for x in appendices.values()
        if isinstance(x, dict) and isinstance(x.get("附录编号"), int)
    )
    appendix_ok = appendix_numbers == list(range(1, 10))
    checks.append({"name": "附录编号完整", "passed": appendix_ok})
    if not appendix_ok:
        errors.append("附录编号必须完整包含1—9")

    reserve = appendices.get("备用车配置及响应时间", {})
    reserve_sum = sum(x.get("数量", 0) for x in reserve.get("明细", []))
    reserve_ok = reserve_sum == reserve.get("合计")
    checks.append({"name": "附录备用车数量闭合", "passed": reserve_ok})
    if not reserve_ok:
        errors.append("附录4备用车数量与合计不一致")

    for name in ["国铁列车地铁覆盖情况", "地铁未覆盖航班"]:
        item = appendices.get(name, {})
        arrivals = item.get("日均到达班次")
        covered = item.get("地铁覆盖班次")
        ratio = item.get("地铁覆盖率（%）")
        nonnegative(f"{name}.日均到达班次", arrivals)
        nonnegative(f"{name}.地铁覆盖班次", covered)
        if isinstance(arrivals, (int, float)) and isinstance(covered, (int, float)):
            if covered > arrivals:
                errors.append(f"{name}地铁覆盖班次不得大于到达班次")
            if arrivals > 0 and isinstance(ratio, (int, float)):
                expected = round(covered * 100 / arrivals, 1)
                ratio_ok = abs(expected - ratio) <= 0.1
                checks.append({"name": f"{name}覆盖率闭合", "passed": ratio_ok})
                if not ratio_ok:
                    warnings.append(f"{name}覆盖率与数量计算结果不一致，报告仍使用业务系统直传覆盖率")
        if not isinstance(ratio, (int, float)) or not 0 <= ratio <= 100:
            errors.append(f"{name}.地铁覆盖率（%）必须在0—100之间")

    summary = parsed_data["运营保障"].get("正文摘要", "")
    if not isinstance(summary, str) or not summary.strip():
        errors.append("运营保障.正文摘要不能为空")
    elif "运营保障安排见附录1" not in summary:
        warnings.append("运营保障正文摘要未明确指向附录1")

    if errors:
        raise ValueError("数据质量校验失败：" + "；".join(errors))

    return {
        "is_valid": True,
        "error_list": [],
        "warn_list": warnings,
        "check_list": checks
    }

def main(holiday_data: dict, forecast_data: dict) -> dict:
    import json

    errors = []
    warnings = []
    facts = []
    holiday = holiday_data.get("节假日概况", {})
    weather = holiday_data.get("天气信息", {})
    line_rows = forecast_data.get("各线路客运量预测", [])
    section_rows = forecast_data.get("重点区段断面客流预测", [])

    line_names = [x.get("线路") for x in line_rows]
    if any(not x for x in line_names):
        errors.append("线路客运量预测存在空线路")
    if len(line_names) != len(set(line_names)):
        errors.append("线路客运量预测存在重复线路")

    facts.append({
        "topic": "summary",
        "priority": 3,
        "source_group": "节假日概况",
        "source_field": "日期范围",
        "fact": f"{holiday.get('节假日名称')}为{holiday.get('开始日期')}至{holiday.get('结束日期')}，共{holiday.get('放假天数')}天"
    })
    if weather.get("概述"):
        facts.append({
            "topic": "summary",
            "priority": 2,
            "source_group": "天气信息",
            "source_field": "概述",
            "fact": weather.get("概述")
        })

    network = forecast_data.get("线网预测汇总", {})
    for field in [
        "节前一日客运量范围（万人次）", "假期日均客运量范围（万人次）",
        "假期前三日日均范围（万人次）", "单日最大客运量范围（万人次）"
    ]:
        value = network.get(field, {})
        if not isinstance(value, dict) or not isinstance(value.get("最小值"), (int, float)) or not isinstance(value.get("最大值"), (int, float)):
            errors.append(f"线网预测汇总.{field}必须包含数值型最小值和最大值")
            continue
        if value["最小值"] > value["最大值"]:
            errors.append(f"线网预测汇总.{field}最小值不得大于最大值")
        facts.append({
            "topic": "forecast",
            "priority": 3,
            "source_group": "客流预测.线网预测汇总",
            "source_field": field,
            "fact": f"{field}为{value['最小值']}-{value['最大值']}万人次"
        })

    for row in line_rows:
        facts.append({
            "topic": "forecast",
            "priority": 2,
            "source_group": "客流预测.各线路客运量预测",
            "source_field": row.get("线路", ""),
            "fact": f"{row.get('线路')}节前一日{row.get('节前一日')}、假期日均{row.get('假期日均')}、单日最大{row.get('单日最大')}，单位{forecast_data.get('客运量单位', '')}"
        })

    for row in section_rows:
        if not row.get("线路"):
            warnings.append("重点区段断面预测存在空线路")
        facts.append({
            "topic": "forecast",
            "priority": 2,
            "source_group": "客流预测.重点区段断面客流预测",
            "source_field": row.get("线路", ""),
            "fact": f"{row.get('线路')}重点方向：{row.get('重点方向', '')}"
        })

    metrics = {
        "holiday": holiday,
        "weather": weather,
        "plan": forecast_data.get("预测方案", {}),
        "network": network,
        "line_rows": line_rows,
        "line_unit": forecast_data.get("客运量单位", ""),
        "section_rows": section_rows,
        "section_unit": forecast_data.get("断面客流单位", ""),
        "serialized_length": len(json.dumps(forecast_data, ensure_ascii=False))
    }

    if errors:
        raise ValueError("假期与客流专题校验失败：" + "；".join(errors))

    return {
        "forecast_result": {
            "status": "完整",
            "metrics": metrics,
            "facts": facts,
            "errors": [],
            "warnings": warnings
        }
    }

def main(focus_data: dict) -> dict:
    errors = []
    warnings = []
    facts = []
    info = focus_data.get("重点信息", {})
    stations_data = focus_data.get("重点车站", {})
    activities = info.get("重点活动", [])
    stations = stations_data.get("明细", [])

    activity_keys = []
    for row in activities:
        key = (row.get("活动名称"), row.get("开始日期"), row.get("活动地点"))
        activity_keys.append(key)
        if not all(key):
            errors.append("重点活动的名称、开始日期和活动地点不能为空")
        if not row.get("开始时间") or not row.get("结束时间"):
            warnings.append(f"活动“{row.get('活动名称', '')}”缺少完整开始或结束时间")
        facts.append({
            "topic": "info",
            "priority": 3,
            "source_group": "重点信息.重点活动",
            "source_field": row.get("活动名称", ""),
            "fact": f"{row.get('活动名称')}于{row.get('开始日期')}至{row.get('结束日期')}在{row.get('活动地点')}举办，预计规模{row.get('预计规模')}{row.get('预计规模单位', '')}"
        })
    if len(activity_keys) != len(set(activity_keys)):
        errors.append("重点活动存在名称、日期和地点完全相同的重复记录")

    station_keys = []
    for row in stations:
        key = (row.get("类型"), row.get("车站"))
        station_keys.append(key)
        if not row.get("车站"):
            errors.append("重点车站名称不能为空")
        if not row.get("重点日期") or not row.get("重点时段"):
            warnings.append(f"重点车站“{row.get('车站', '')}”缺少日期或时段")
        facts.append({
            "topic": "station",
            "priority": 2,
            "source_group": "重点车站.明细",
            "source_field": row.get("车站", ""),
            "fact": f"{row.get('车站')}重点日期{row.get('重点日期')}、重点时段{row.get('重点时段')}，风险点为{row.get('风险点')}"
        })
    if len(station_keys) != len(set(station_keys)):
        warnings.append("同一类型下存在重复重点车站记录")

    if errors:
        raise ValueError("活动与重点车站专题校验失败：" + "；".join(errors))

    return {
        "focus_result": {
            "status": "完整",
            "metrics": {
                "activities": activities,
                "activity_count": len(activities),
                "selection_criteria": stations_data.get("筛选依据", []),
                "stations": stations,
                "station_count": len(stations)
            },
            "facts": facts,
            "errors": [],
            "warnings": warnings
        }
    }

def main(transport_data: dict, appendix_data: dict) -> dict:
    errors = []
    warnings = []
    checks = []
    facts = []

    pre = transport_data.get("节前一日", {})
    pre_rows = pre.get("各线路方案", [])
    pre_online = sum(x.get("上线列车数", 0) for x in pre_rows)
    pre_reserve = sum(x.get("备用车数", 0) for x in pre_rows)
    pre_online_ok = pre_online == pre.get("上线列车合计")
    pre_reserve_ok = pre_reserve == pre.get("备用车合计")
    checks.extend([
        {"name": "节前上线列车闭合", "passed": pre_online_ok},
        {"name": "节前备用车闭合", "passed": pre_reserve_ok}
    ])
    if not pre_online_ok:
        errors.append("节前上线列车数不闭合")
    if not pre_reserve_ok:
        errors.append("节前备用车数不闭合")

    holiday = transport_data.get("假期期间", {})
    grouped = {}
    for row in holiday.get("各线路方案", []):
        line = row.get("线路")
        if not line:
            errors.append("假期线路方案存在空线路")
            continue
        current = grouped.setdefault(line, {"online": 0, "reserve": 0})
        current["online"] = max(current["online"], row.get("上线列车数", 0))
        current["reserve"] = max(current["reserve"], row.get("备用车数", 0))
    holiday_online = sum(x["online"] for x in grouped.values())
    holiday_reserve = sum(x["reserve"] for x in grouped.values())
    holiday_online_ok = holiday_online == holiday.get("最大上线列车数")
    holiday_reserve_ok = holiday_reserve == holiday.get("最大备用车数")
    checks.extend([
        {"name": "假期最大上线列车闭合", "passed": holiday_online_ok},
        {"name": "假期最大备用车闭合", "passed": holiday_reserve_ok}
    ])
    if not holiday_online_ok:
        errors.append("假期最大上线列车数与各线路最大配置不一致")
    if not holiday_reserve_ok:
        errors.append("假期最大备用车数与各线路最大配置不一致")

    reserve = appendix_data.get("备用车配置及响应时间", {})
    reserve_sum = sum(x.get("数量", 0) for x in reserve.get("明细", []))
    reserve_ok = reserve_sum == reserve.get("合计")
    checks.append({"name": "附录4备用车闭合", "passed": reserve_ok})
    if not reserve_ok:
        errors.append("附录4备用车数量与合计不一致")
    if reserve.get("合计") != holiday.get("最大备用车数"):
        warnings.append("附录4备用车合计与假期最大备用车数不一致")

    coverage = {}
    for name in ["国铁列车地铁覆盖情况", "地铁未覆盖航班"]:
        item = appendix_data.get(name, {})
        arrivals = item.get("日均到达班次", 0)
        covered = item.get("地铁覆盖班次", 0)
        ratio = item.get("地铁覆盖率（%）", 0)
        if covered > arrivals:
            errors.append(f"{name}覆盖班次大于到达班次")
        expected = round(covered * 100 / arrivals, 1) if arrivals else 0
        if abs(expected - ratio) > 0.1:
            warnings.append(f"{name}覆盖率与数量不一致，正文仍使用业务系统直传值{ratio}%")
        coverage[name] = {"arrivals": arrivals, "covered": covered, "ratio": ratio}

    facts.extend([
        {
            "topic": "transport",
            "priority": 3,
            "source_group": "运输安排.节前一日",
            "source_field": "线网合计",
            "fact": f"节前一日上线列车{pre.get('上线列车合计')}列、备用车{pre.get('备用车合计')}列"
        },
        {
            "topic": "transport",
            "priority": 3,
            "source_group": "运输安排.假期期间",
            "source_field": "最大配置",
            "fact": f"假期最大上线列车{holiday.get('最大上线列车数')}列、最大备用车{holiday.get('最大备用车数')}列"
        }
    ])
    for row in pre_rows:
        facts.append({
            "topic": "transport",
            "priority": 2,
            "source_group": "运输安排.节前一日.各线路方案",
            "source_field": row.get("线路", ""),
            "fact": f"{row.get('线路')}最小行车间隔{row.get('最小行车间隔')}，上线{row.get('上线列车数')}列，备用{row.get('备用车数')}列"
        })

    if errors:
        raise ValueError("运输安排校验失败：" + "；".join(errors))

    return {
        "transport_result": {
            "status": "完整",
            "metrics": {
                "transport": transport_data,
                "reserve_appendix": reserve,
                "coverage": coverage
            },
            "checks": checks,
            "facts": facts,
            "errors": [],
            "warnings": warnings
        }
    }

def main(assure_data: dict, appendix_data: dict) -> dict:
    errors = []
    warnings = []
    facts = []

    summary = assure_data.get("正文摘要", "")
    if not isinstance(summary, str) or not summary.strip():
        errors.append("运营保障正文摘要不能为空")
    elif "运营保障安排见附录1" not in summary:
        warnings.append("正文摘要未指向附录1")

    required_sections = [
        "组织保障", "安全保障", "行车组织保障", "客运组织保障",
        "客运量及票款收益", "客运服务保障", "票务保障", "设备保障",
        "施工管理", "信息报送", "宣传及舆情", "人员及物资"
    ]
    missing_sections = [x for x in required_sections if x not in assure_data]
    if missing_sections:
        errors.append(f"缺少运营保障分类：{missing_sections}")

    numbers = []
    for name, value in appendix_data.items():
        if isinstance(value, dict) and isinstance(value.get("附录编号"), int):
            numbers.append(value["附录编号"])
    if sorted(numbers) != list(range(1, 10)):
        errors.append("附录编号必须完整包含1—9")

    for name in [
        "各线路重点关注时段及区段", "备用车配置及响应时间",
        "国铁列车地铁覆盖情况", "地铁未覆盖航班",
        "设备设施运行保障方案", "重点设备设施检修项点", "车站客流组织情景"
    ]:
        item = appendix_data.get(name, {})
        rows = item.get("明细") or item.get("工作阶段") or item.get("检查项目")
        if rows == []:
            warnings.append(f"附录数据“{name}”没有明细")

    facts.append({
        "topic": "summary",
        "priority": 3,
        "source_group": "运营保障",
        "source_field": "正文摘要",
        "fact": summary
    })
    facts.append({
        "topic": "summary",
        "priority": 2,
        "source_group": "附录数据",
        "source_field": "附录编号",
        "fact": "附录1至附录9数据齐全" if sorted(numbers) == list(range(1, 10)) else "附录编号不完整"
    })

    if errors:
        raise ValueError("运营保障与附录校验失败：" + "；".join(errors))

    return {
        "assure_result": {
            "status": "完整",
            "metrics": {
                "main_summary": summary,
                "assurance": assure_data,
                "appendices": appendix_data,
                "section_count": len(required_sections) - len(missing_sections)
            },
            "facts": facts,
            "errors": [],
            "warnings": warnings
        }
    }

def main(
    forecast_result: dict,
    focus_result: dict,
    transport_result: dict,
    assure_result: dict
) -> dict:
    import json

    def compact(value, depth=0):
        if depth > 7:
            return None
        if isinstance(value, dict):
            return {
                str(key): compact(child, depth + 1)
                for key, child in value.items()
            }
        if isinstance(value, list):
            return [compact(child, depth + 1) for child in value[:20]]
        if isinstance(value, str):
            return value[:500]
        return value

    focus_metrics = focus_result.get("metrics", {})
    assure_metrics = assure_result.get("metrics", {})
    packets = {
        "forecast": compact(forecast_result),
        "info": compact({
            "status": focus_result.get("status"),
            "activities": focus_metrics.get("activities", []),
            "facts": [x for x in focus_result.get("facts", []) if x.get("topic") == "info"],
            "warnings": focus_result.get("warnings", [])
        }),
        "station": compact({
            "status": focus_result.get("status"),
            "selection_criteria": focus_metrics.get("selection_criteria", []),
            "stations": focus_metrics.get("stations", []),
            "facts": [x for x in focus_result.get("facts", []) if x.get("topic") == "station"],
            "warnings": focus_result.get("warnings", [])
        }),
        "transport": compact(transport_result),
        "summary": compact({
            "holiday": forecast_result.get("metrics", {}).get("holiday", {}),
            "weather": forecast_result.get("metrics", {}).get("weather", {}),
            "network": forecast_result.get("metrics", {}).get("network", {}),
            "main_summary": assure_metrics.get("main_summary", ""),
            "assurance_status": assure_result.get("status")
        })
    }
    for name, packet in packets.items():
        if isinstance(packet, dict):
            packet["serialized_length"] = len(json.dumps(packet, ensure_ascii=False))

    return {"topic_packets": packets}

def main(
    forecast_md: str,
    info_md: str,
    station_md: str,
    transport_md: str,
    model_inputs: dict
) -> dict:
    import json
    import re

    def clean(value):
        text = str(value or "").strip()
        if text.startswith("```"):
            text = re.sub(r"^```(?:markdown|md)?\s*", "", text)
            text = re.sub(r"\s*```$", "", text)
        return text.strip()

    def numbers(value):
        serialized = json.dumps(value, ensure_ascii=False)
        return set(re.findall(r"(?<![A-Za-z])\d+(?:\.\d+)?", serialized))

    raw = {
        "forecast": forecast_md,
        "info": info_md,
        "station": station_md,
        "transport": transport_md
    }
    headings = {
        "forecast": "## 二、客流预测",
        "info": "## 三、重点信息",
        "station": "## 四、重点车站",
        "transport": "## 五、运输安排"
    }
    max_lengths = {
        "forecast": 8000,
        "info": 7000,
        "station": 7000,
        "transport": 9000
    }
    chapters = {}
    reviews = []
    warnings = []
    hard_errors = []

    for topic, value in raw.items():
        text = clean(value)
        if not text:
            hard_errors.append(f"{topic}章节正文为空")
            continue
        if text.startswith("{") or text.startswith("["):
            hard_errors.append(f"{topic}章节输出为JSON而不是Markdown")
        if not text.startswith(headings[topic]):
            hard_errors.append(f"{topic}章节标题不正确，应以“{headings[topic]}”开头")
        if text.count(headings[topic]) != 1:
            hard_errors.append(f"{topic}章节标题必须且只能出现一次")
        if len(text) > max_lengths[topic]:
            hard_errors.append(f"{topic}章节超过{max_lengths[topic]}字符")

        allowed = numbers(model_inputs.get(topic, {}))
        output = numbers(text)
        unknown = sorted(x for x in output - allowed if float(x) > 20)
        if unknown:
            warnings.append(f"{topic}章节出现需复核数字：{unknown[:10]}")

        marker = "### 专题结论"
        if marker in text:
            topic_summary = text.split(marker, 1)[1].strip()[:600]
        else:
            hard_errors.append(f"{topic}章节缺少“### 专题结论”")
            topic_summary = text[-600:]

        chapters[topic] = text
        reviews.append({
            "topic": topic,
            "heading": headings[topic],
            "content_length": len(text),
            "topic_summary": topic_summary
        })

    if hard_errors:
        raise ValueError("模型输出校验失败：" + "；".join(hard_errors))

    return {
        "chapter_texts": chapters,
        "chapter_review": reviews,
        "model_warns": warnings
    }

def main(task_ctx: dict, chapter_texts: dict, summary_md: str, parsed_data: dict) -> dict:
    import json
    import re

    warnings = []

    def text_value(value):
        if value is None:
            return ""
        if isinstance(value, list):
            return "、".join(text_value(x) for x in value)
        if isinstance(value, dict):
            return "；".join(f"{k}：{text_value(v)}" for k, v in value.items())
        return str(value).replace("|", "\\|").replace("\n", "<br>")

    def table(headers, rows):
        if not rows:
            return ""
        lines = [
            "| " + " | ".join(headers) + " |",
            "|" + "|".join(["---"] * len(headers)) + "|"
        ]
        for row in rows:
            lines.append("| " + " | ".join(text_value(row.get(h, "")) for h in headers) + " |")
        return "\n".join(lines)

    def numbered(items):
        return "\n".join(f"{i}. {text_value(item)}" for i, item in enumerate(items, 1))

    def render_value(value):
        if isinstance(value, list):
            if not value:
                return ""
            if all(isinstance(x, dict) for x in value):
                headers = []
                for row in value:
                    for key in row:
                        if key not in headers:
                            headers.append(key)
                return table(headers, value)
            return numbered(value)
        if isinstance(value, dict):
            parts = []
            for key, child in value.items():
                parts.append(f"### {key}\n\n{render_value(child)}")
            return "\n\n".join(parts)
        return text_value(value)

    def numeric_tokens(value):
        text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)
        tokens = set()
        for raw in re.findall(r"(?<![A-Za-z0-9])\d+(?:\.\d+)?", text):
            number = float(raw)
            token = str(int(number)) if number.is_integer() else format(number, ".12g")
            tokens.add(token)
        return tokens

    def normalized_text(value):
        return re.sub(r"\s+", "", str(value or "")).rstrip("。")

    def split_summary(value):
        if not isinstance(value, str):
            raise TypeError("N19输出summary_md必须为String")
        text = value.strip()
        if not text:
            raise ValueError("N19输出summary_md为空")
        if text.startswith("```") or text.startswith("{") or text.startswith("["):
            raise ValueError("N19必须直接输出Markdown字符串，不能输出代码围栏或JSON")
        if len(text) > 3500:
            raise ValueError("N19输出超过3500字符")

        h1 = "## 一、假期概况"
        h6 = "## 六、运营保障要求"
        for heading in [h1, h6]:
            if len(re.findall(rf"(?m)^{re.escape(heading)}\s*$", text)) != 1:
                raise ValueError(f"标题必须且只能出现一次：{heading}")
        p1 = text.index(h1)
        p6 = text.index(h6)
        if p1 != 0 or p1 >= p6:
            raise ValueError("N19章节标题顺序错误或第一章前存在多余文字")
        chapter_1 = text[p1:p6].strip()
        chapter_6 = text[p6:].strip()
        body_6 = chapter_6[len(h6):].strip()
        paragraphs = [x for x in re.split(r"\n\s*\n", body_6) if x.strip()]
        if len(paragraphs) != 1:
            raise ValueError("第六章运营保障要求必须只有一个自然段")
        return {"chapter_1": chapter_1, "chapter_6": chapter_6, "chapter_6_body": body_6}

    summary = split_summary(summary_md)

    allowed_summary_sources = {
        "任务信息": parsed_data.get("任务信息", {}),
        "文档标题": parsed_data.get("文档信息", {}).get("文档标题", ""),
        "节假日概况": parsed_data.get("节假日概况", {}),
        "天气信息": parsed_data.get("天气信息", {}),
        "客流预测": {
            "预测方案": parsed_data.get("客流预测", {}).get("预测方案", {}),
            "线网预测汇总": parsed_data.get("客流预测", {}).get("线网预测汇总", {})
        }
    }
    unknown_nums = sorted(
        numeric_tokens(summary["chapter_1"]) - numeric_tokens(allowed_summary_sources),
        key=lambda x: float(x)
    )
    if unknown_nums:
        raise ValueError(f"第一章出现输入来源外数字：{unknown_nums[:10]}")

    expected_summary = parsed_data.get("运营保障", {}).get("正文摘要", "")
    if not isinstance(expected_summary, str) or not expected_summary.strip():
        raise ValueError("运营保障.正文摘要不能为空")
    expected_summary = expected_summary.strip()
    if normalized_text(summary["chapter_6_body"]) != normalized_text(expected_summary):
        warnings.append("第六章已按运营保障.正文摘要强制替换")
    summary["chapter_6"] = "## 六、运营保障要求\n\n" + expected_summary

    required_topics = ["forecast", "info", "station", "transport"]
    missing = [x for x in required_topics if not chapter_texts.get(x)]
    if missing:
        raise ValueError(f"缺少专题章节：{missing}")

    title = task_ctx.get("document_title") or parsed_data.get("文档信息", {}).get("文档标题", "节假日运营组织方案")
    parts = [
        f"# {title}",
        summary["chapter_1"],
        chapter_texts["forecast"].strip(),
        chapter_texts["info"].strip(),
        chapter_texts["station"].strip(),
        chapter_texts["transport"].strip(),
        summary["chapter_6"]
    ]

    appendix_titles = parsed_data.get("文档信息", {}).get("附录目录", [])
    if len(appendix_titles) != 9:
        raise ValueError("文档信息.附录目录必须包含9项")
    parts.append("附录：\n\n" + "\n".join(f"{i}. {title_text.split(' ', 1)[-1]}。" for i, title_text in enumerate(appendix_titles, 1)))
    parts.append("---")

    assurance = parsed_data["运营保障"]
    parts.extend(["# 附录1", "# 运营保障安排"])
    assurance_order = [
        "组织保障", "安全保障", "行车组织保障", "客运组织保障",
        "客运量及票款收益", "客运服务保障", "票务保障", "设备保障",
        "施工管理", "信息报送", "宣传及舆情", "人员及物资"
    ]
    chinese_numbers = ["一", "二", "三", "四", "五", "六", "七", "八", "九", "十", "十一", "十二"]
    for index, key in enumerate(assurance_order):
        value = assurance.get(key)
        if value is None:
            raise ValueError(f"运营保障缺少：{key}")
        parts.append(f"## {chinese_numbers[index]}、{key}\n\n{render_value(value)}")

    app = parsed_data["附录数据"]
    app2 = app["各线路重点关注时段及区段"]
    parts.extend([
        "# 附录2",
        "# 各线路重点关注时段及重点区段",
        table(["线路", "重点日期", "重点时段", "重点区段及方向", "主要客流"], app2.get("明细", []))
    ])

    op_rows = parsed_data["运输安排"].get("运营时间", {}).get("明细", [])
    parts.extend([
        "# 附录3",
        "# 2026年国庆节假期各线路延时时长",
        table(["线路", "首班车调整", "末班车调整", "重点衔接"], op_rows)
    ])

    app4 = app["备用车配置及响应时间"]
    parts.extend([
        "# 附录4",
        "# 各线路备用车位置及到达重点站运行时间表",
        f"全线网共安排备用车{app4.get('合计')}列。",
        table(["线路", "备用车存放位置", "数量", "重点支援车站", "响应时间"], app4.get("明细", []))
    ])

    app5 = app["国铁列车地铁覆盖情况"]
    parts.extend([
        "# 附录5",
        "# 国庆节假期国铁列次覆盖情况",
        f"日均到达{app5.get('日均到达班次')}列，地铁覆盖{app5.get('地铁覆盖班次')}列，覆盖率{app5.get('地铁覆盖率（%）')}%。",
        table(["枢纽", "日均到达班次", "地铁覆盖班次", "地铁覆盖率（%）", "未覆盖班次", "未覆盖时段"], app5.get("枢纽汇总", [])),
        "## 重点未覆盖列车",
        table(["枢纽", "车次", "到达时间", "地铁衔接情况", "地面交通衔接"], app5.get("未覆盖列车", []))
    ])

    app6 = app["地铁未覆盖航班"]
    parts.extend([
        "# 附录6",
        "# 国庆节假期地铁未覆盖航班架次",
        f"日均到达{app6.get('日均到达班次')}架次，地铁覆盖{app6.get('地铁覆盖班次')}架次，覆盖率{app6.get('地铁覆盖率（%）')}%，主要未覆盖时段为{app6.get('主要未覆盖时段')}。",
        table(["航班号", "始发地", "到达时间", "到达航站楼", "地铁覆盖情况", "地面交通衔接"], app6.get("明细", [])),
        f"**延误联动安排：** {text_value(app6.get('延误联动安排', ''))}"
    ])

    app7 = app["设备设施运行保障方案"]
    parts.extend([
        "# 附录7",
        "# 设备设施运行保障方案",
        "## 工作阶段",
        table(["阶段", "时间", "工作内容", "牵头单位"], app7.get("工作阶段", [])),
        "## 各专业要求",
        table(["专业", "要求"], app7.get("各专业要求", []))
    ])

    app8 = app["重点设备设施检修项点"]
    parts.extend([
        "# 附录8",
        "# 重点设备设施关键检修项点明细",
        table(["专业", "检查要点"], app8.get("检查项目", []))
    ])

    app9 = app["车站客流组织情景"]
    parts.extend([
        "# 附录9",
        "# 国庆节假期车站客流流线组织关键场景及应对措施清单",
        table(["车站", "情景", "重点时段", "启动条件", "处置措施", "恢复条件"], app9.get("明细", []))
    ])
    parts.append("本方案中运输安排及运营时间以正式运作命令为准，各专业保障要求按照相应专项方案执行。")

    report = "\n\n".join(part.strip() for part in parts if str(part).strip()) + "\n"
    if "### 专题结论" in report:
        report = re.sub(r"\n### 专题结论\n.*?(?=\n## |\n# 附录|\Z)", "", report, flags=re.S)
        warnings.append("最终组装时已移除专题模型内部的专题结论段")

    return {
        "report_md": report,
        "report_len": len(report),
        "output_warns": warnings
    }
